schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/sdd/readiness-checklist.json",
  "title": "Readiness Checklist (readiness.md)",
  "type": "object",
  "required": ["feature_id", "path", "reviewer", "items", "verdict"],
  "additionalProperties": false,
  "properties": {
    "feature_id": {"type": "string", "pattern": "^F[0-9]{3,}$"},
    "path": {"type": "string", "pattern": "^features/in-progress/F[0-9]{3,}-[a-z0-9-]+/readiness\\.md$"},
    "reviewer": {"type": "string", "minLength": 2},
    "verdict": {"type": "string", "enum": ["done", "blocked"]},
    "items": {
      "type": "array",
      "minItems": 10,
      "maxItems": 10,
      "items": {
        "type": "object",
        "required": ["n", "title", "applies", "ticked"],
        "additionalProperties": false,
        "properties": {
          "n": {"type": "integer", "minimum": 1, "maximum": 10},
          "title": {"type": "string", "minLength": 1},
          "applies": {"type": "boolean"},
          "ticked": {"type": "boolean"},
          "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "format": "uri-reference", "minLength": 1}},
          "reason": {"type": "string", "minLength": 1}
        },
        "allOf": [
          {"if": {"properties": {"ticked": {"const": true}}}, "then": {"required": ["evidence"]}},
          {"if": {"properties": {"applies": {"const": false}}}, "then": {"required": ["reason"], "properties": {"ticked": {"const": false}}}}
        ]
      }
    }
  }
}

output-contract.example:
{
  "feature_id": "F012",
  "path": "features/in-progress/F012-billing-export/readiness.md",
  "reviewer": "team",
  "verdict": "done",
  "items": [
    {"n": 1, "title": "ACs evidence", "applies": true, "ticked": true},
    {"n": 5, "title": "API tests", "applies": false, "ticked": false},
    {"n": 9, "title": "surface coupling", "applies": true, "ticked": true, "evidence": ["no public surface"]}
  ]
}
